// Checks the phone page's protocol code against packets generated by the C++ firmware code.
//   g++ -std=c++11 -I../include -o gen_packets gen_packets.cpp && ./gen_packets | node test_page_core.js
const fs = require('fs');
const path = require('path');
const vm = require('vm');

const html = fs.readFileSync(path.join(__dirname, '..', 'app', 'index.html'), 'utf8');
const script = html.match(/<script>([\s\S]*)<\/script>/)[1];

// 1. The whole script must at least parse.
new vm.Script(script);

// 2. Pull out the pure CORE block and run it on its own.
const core = script.split('// ===== BEGIN CORE')[1].split('// ===== END CORE =====')[0]
  .split('\n').slice(1).join('\n');  // drop the rest of the BEGIN marker line
const ctx = {};
vm.createContext(ctx);
vm.runInContext(core + '\nthis.api = { parseEvent, pingPacket, cmdPacket, estimateOffset, SVC, CMD, EVT };', ctx);
const api = ctx.api;

let failures = 0;
function check(cond, msg) { if (!cond) { console.log('  FAIL: ' + msg); failures++; } }

function dvFromHex(h) {
  const b = Buffer.from(h, 'hex');
  return new DataView(b.buffer, b.byteOffset, b.byteLength);
}

const lines = fs.readFileSync(0, 'utf8').trim().split('\n');
const pk = {};
lines.forEach((l) => { const [k, v] = l.split(' '); pk[k] = v; });

let e = api.parseEvent(dvFromHex(pk.pong));
check(e && e.type === 'pong' && e.id === 0xA1B2C3D4 && e.tDev === 123456789012345, 'pong parses');
e = api.parseEvent(dvFromHex(pk.trigger));
check(e && e.type === 'trigger' && e.seq === 513 && e.tDev === 9876543210, 'trigger parses');
e = api.parseEvent(dvFromHex(pk.status));
check(e && e.type === 'status' && e.state === 1 && e.armed === true && e.rate === 830 && e.expected === 833,
      'status parses');
check(api.parseEvent(dvFromHex('09')) === null, 'unknown type ignored');
check(api.parseEvent(dvFromHex('0201')) === null, 'short packet ignored');

// Commands: what the page sends must match what the firmware's handle_command expects.
check(Buffer.from(api.cmdPacket('A')).toString('hex') === '41', 'arm is 0x41');
check(Buffer.from(api.cmdPacket('D')).toString('hex') === '44', 'disarm is 0x44');
check(Buffer.from(api.pingPacket(0xA1B2C3D4)).toString('hex') === '50d4c3b2a1', 'ping is P + u32 LE');

// Offset estimate on simulated delays, same model as the C++ test.
let seed = 12345;
const rnd = () => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed / 0x7fffffff; };
const errs = [];
for (let k = 0; k < 2000; k++) {
  const trueOffset = (rnd() - 0.5) * 1e10;
  const samples = [];
  let t = 1e6;
  for (let i = 0; i < 15; i++) {
    const up = 2000 + rnd() * 13000, down = 2000 + rnd() * 13000;
    samples.push({ tSend: t, tDev: t + up + trueOffset, tRecv: t + up + down });
    t += 50000;
  }
  errs.push(Math.abs(api.estimateOffset(samples).offset - trueOffset));
}
errs.sort((a, b) => a - b);
console.log('page offset error with 15 pings, 2-15 ms delays: median ' + errs[1000].toFixed(0) +
            ' us, p95 ' + errs[1900].toFixed(0) + ' us, worst ' + errs[1999].toFixed(0) + ' us');
check(errs[1999] <= 6500 + 1, 'error within half the delay range');
check(api.estimateOffset([]) === null, 'no samples gives null');

console.log(failures ? failures + ' check(s) FAILED' : 'page core checks passed');
process.exit(failures ? 1 : 0);
